const fs = await import("node:fs");
const t = fs.readFileSync("C:/Users/jjq21/AppData/Local/Temp/ofm-subs-out.txt", "utf8");
// 打印全部正文（每条 400 字）
const blocks = t.split("--- ");
const want = [
  "40K ARR in one month",
  "After 13 months and 3 failed projects",
  "talked to 12 micro saas founders",
  "the fastest path to $5K/month",
  "I built a boring directory that's making $10k",
  "From Living in My Car to $150K in 15 Months",
  "Built a programmatic SEO site to 700K impressions",
  "rebuilt my window cleaner's website",
];
for (const b of blocks) {
  for (const w of want) {
    if (b.includes(w)) {
      console.log("\n========== " + b.slice(0, 100).split("\n")[0] + " ==========");
      console.log(b.slice(0, 1400));
    }
  }
}
